PN={'london': '런던', 'antwerp': '안트베르펀', 'seville': '세비야', 'venice': '베네치아 공화국', 'lisbon': '리스본', 'rotterdam': '로테르담', 'plymouth': '플리머스', 'la_rochelle': '라로셸', 'porto': '포르투', 'cadiz': '카디스', 'smyrna': '이즈미르', 'mombasa': '몸바사', 'calicut': '캘리컷', 'cochin': '코친', 'canton': '광저우', 'amoy': '샤먼', 'nagasaki': '나가사키', 'osaka': '오사카', 'incheon': '인천', 'campeche': '캄페체'}
REW = [(300,8,40),(500,12,70),(900,20,120),(1500,35,200)]
def q(s): return '"'+s.replace('\\','\\\\').replace('"','\\"')+'"'
out=["--!strict","-- 서막 메인 퀘스트: 시작 국가별 4장 (사연 → 길 → 목표 → 학자). 자동 생성: tools/gen_prologue.py 로 만든 뒤 다듬는다.","-- 시작 국가의 첫 동료와 함께 가는 이야기. nation 이 다르면 보이지 않는다.","local Q = {}","local HAND: { [string]: { string } } = {}",""]
for d in N:
    prev=None
    for i in range(4):
        name,story,end=d["t"][i]
        qid=f"pr_{d['n']}_{i+1}"
        coins,fame,xp=REW[i]
        if i==0: kind=f'kind = "deliver", goodId = {q(d["g1"][0])}, portId = {q(d["g1"][1])}, amount = {d["g1"][2]}'; summ=f'{GN[d["g1"][0]]} {d["g1"][2]}개를 {PN[d["g1"][1]]}에 납품'
        elif i==1: kind='kind = "visit", amount = 4'; summ="서로 다른 항구 4곳 방문"
        elif i==2: kind=f'kind = "deliver", goodId = {q(d["g3"][0])}, portId = {q(d["g3"][1])}, amount = {d["g3"][2]}'; summ=f'{GN[d["g3"][0]]} {d["g3"][2]}개를 {PN[d["g3"][1]]}에 납품'
        else: kind='kind = "understand", amount = 3'; summ="지식 3가지를 학자에게 보고해 이해"
        out.append(f'table.insert(Q, {{ id = {q(qid)}, name = {q(name)}, summary = {q("서막 · "+d["series"]+" — "+summ)}, {kind}, nation = {q(d["n"])}, strand = "main",')
        out.append(f'\trewardCoins = {coins}, rewardFame = {fame}, rewardCareer = {q(d["career"])}, rewardXp = {xp}{", after = "+q(prev) if prev else ""} }})')
        out.append(f'HAND[{q(qid)}] = {{ {q(story)}, {q(end)} }}')
        prev=qid
out.append("")
out.append("return { Quests = Q, Hand = HAND }")
open('src/ReplicatedStorage/Shared/PrologueQuests.luau','w',encoding='utf-8').write("\n".join(out)+"\n")
print("ok",len(N)*4)
